<script setup lang="ts">
import { ArrowRight, Minus, Plus, ShoppingBag, Trash2 } from '@lucide/vue';
const config = useRuntimeConfig(); const { cartSession, cart, loadCart, user } = useStorefront(); const loading = ref(true); const busy = ref(false); const success = ref<any>(null); const payment = ref<any>(null); const error = ref(''); const address = reactive({ recipientName: '', phone: '', city: '', street: '', house: '', apartment: '', postalCode: '' });
async function change(item:any, quantity:number) { cart.value = await $fetch(`/cart/items/${item.id}`, { baseURL:config.public.apiBase, method:'PATCH', headers:{'x-cart-session':cartSession.value}, body:{quantity:Math.max(1,quantity)} }); }
async function remove(item:any) { cart.value = await $fetch(`/cart/items/${item.id}`, { baseURL:config.public.apiBase, method:'DELETE', headers:{'x-cart-session':cartSession.value} }); }
async function checkout() { error.value=''; busy.value=true; try { success.value=await $fetch<any>('/orders/checkout',{baseURL:config.public.apiBase,method:'POST',headers:{'x-cart-session':cartSession.value},body:{shippingAddress:address,paymentMethod:'YOOKASSA'}}); payment.value=await $fetch<any>(`/payments/orders/${success.value.orderNumber}`,{baseURL:config.public.apiBase,method:'POST',body:{returnUrl:window.location.origin+'/account'}}); await loadCart(); } catch(e:any){error.value=e?.data?.message||'Не удалось оформить заказ';} finally{busy.value=false;} }
onMounted(async()=>{await loadCart(); loading.value=false; if(user.value){address.recipientName=[user.value.firstName,user.value.lastName].filter(Boolean).join(' ');}}); useSeoMeta({title:'Корзина — SARKISIAN BRAND'});
</script>
<template><SiteShell><div class="sb-cart-page"><div class="sb-breadcrumbs"><NuxtLink to="/">Главная</NuxtLink><span>/</span><span>Корзина</span></div><div class="sb-page-title"><p>ВАШ ЗАКАЗ</p><h1>Корзина</h1><span v-if="cart">{{ cart.items?.length || 0 }} позиций</span></div><div v-if="success" class="sb-order-success"><span>Заказ оформлен</span><h2>{{ success.orderNumber }}</h2><p>Мы получили заказ и передали его в единую систему обработки.</p><a v-if="payment?.confirmationUrl" :href="payment.confirmationUrl" class="sb-primary">Перейти к оплате <ArrowRight :size="17" /></a><NuxtLink v-else to="/account" class="sb-primary">Открыть мои заказы</NuxtLink></div><div v-else-if="loading" class="sb-state">Загружаем корзину…</div><div v-else-if="cart?.items?.length" class="sb-cart-layout"><section class="sb-cart-items"><article v-for="item in cart.items" :key="item.id" class="sb-cart-item"><div class="sb-cart-thumb"><img v-if="storefrontProductImage(item.variant.product)" :src="storefrontProductImage(item.variant.product)!" :alt="item.variant.product.nameRu" /><span v-else>S</span></div><div><h2>{{ item.variant.product.nameRu }}</h2><p>{{ item.variant.name }} · {{ item.variant.sku }}</p><div class="sb-quantity"><button :disabled="item.quantity<=1" @click="change(item,item.quantity-1)"><Minus :size="14" /></button><b>{{ item.quantity }}</b><button @click="change(item,item.quantity+1)"><Plus :size="14" /></button></div></div><strong>{{ (Number(item.variant.price)*item.quantity).toLocaleString('ru-RU') }} ₽</strong><button class="sb-remove" aria-label="Удалить товар" @click="remove(item)"><Trash2 :size="18" /></button></article></section><aside class="sb-checkout"><p class="sb-kicker">ОФОРМЛЕНИЕ</p><h2>Доставка</h2><label>Получатель<input v-model="address.recipientName" required /></label><label>Телефон<input v-model="address.phone" placeholder="+7 999 000-00-00" required /></label><div class="sb-checkout-row"><label>Город<input v-model="address.city" required /></label><label>Индекс<input v-model="address.postalCode" /></label></div><label>Улица<input v-model="address.street" required /></label><div class="sb-checkout-row"><label>Дом<input v-model="address.house" required /></label><label>Квартира<input v-model="address.apartment" /></label></div><div class="sb-checkout-total"><span>Товары</span><b>{{ Number(cart.total).toLocaleString('ru-RU') }} ₽</b><span>Доставка</span><b>Рассчитаем</b><strong>Итого</strong><strong>{{ Number(cart.total).toLocaleString('ru-RU') }} ₽</strong></div><p v-if="error" class="sb-form-error">{{ error }}</p><button class="sb-primary" :disabled="busy||!address.city||!address.street||!address.house||!address.phone" @click="checkout"><ShoppingBag :size="18" />{{ busy?'Оформляем…':'Оформить заказ' }}</button><small>Нажимая кнопку, вы соглашаетесь с условиями оферты и обработки персональных данных.</small></aside></div><div v-else class="sb-empty"><ShoppingBag :size="39" /><h2>Корзина пока пуста</h2><p>Добавьте продукты, с которыми хочется работать.</p><NuxtLink to="/catalog" class="sb-primary">Перейти в каталог</NuxtLink></div></div></SiteShell></template>
